        for (j = 0; j < 3; j++)
            davenport_k->m[i + 1][j + 1] = b.m[i][j] + b.m[j][i] - ((i == j) ? sigma : 0.0);
    }

    *weight_sum = wsum;
    return ADCS_OK;
}
